const updateProductDocument = `-- name: UpdateProductDocument :one
UPDATE documents SET title=$1::text,category=$2::text,
 body=$3::text,frontmatter_yaml=$4::text,
 policy=$5::jsonb,visibility=$6::text,
 status=$7::text,published_at=$8::timestamptz,
 published_by=(SELECT id FROM members WHERE public_id=$9::uuid),
 deleted_at=$10::timestamptz,
 deleted_by=(SELECT id FROM members WHERE public_id=$11::uuid),
 version=version+1,updated_at=$12::timestamptz
WHERE public_id=$13::uuid AND version=$14::int
RETURNING id AS internal_id,public_id AS id,version,updated_at,published_at,deleted_at
`

type UpdateProductDocumentParams struct {
	Title           string             `json:"title"`
	Category        pgtype.Text        `json:"category"`
	Body            string             `json:"body"`
	FrontmatterYaml pgtype.Text        `json:"frontmatter_yaml"`
	Policy          []byte             `json:"policy"`
	Visibility      string             `json:"visibility"`
	Status          string             `json:"status"`
	PublishedAt     pgtype.Timestamptz `json:"published_at"`
	PublishedBy     pgtype.UUID        `json:"published_by"`
	DeletedAt       pgtype.Timestamptz `json:"deleted_at"`
	DeletedBy       pgtype.UUID        `json:"deleted_by"`
	At              pgtype.Timestamptz `json:"at"`
	ID              pgtype.UUID        `json:"id"`
	ExpectedVersion int32              `json:"expected_version"`
}

type UpdateProductDocumentRow struct {
	InternalID  int64              `json:"internal_id"`
	ID          pgtype.UUID        `json:"id"`
	Version     int32              `json:"version"`
	UpdatedAt   pgtype.Timestamptz `json:"updated_at"`
	PublishedAt pgtype.Timestamptz `json:"published_at"`
	DeletedAt   pgtype.Timestamptz `json:"deleted_at"`
}

func (q *Queries) UpdateProductDocument(ctx context.Context, arg UpdateProductDocumentParams) (UpdateProductDocumentRow, error) {
	row := q.db.QueryRow(ctx, updateProductDocument,
		arg.Title,
		arg.Category,
		arg.Body,
		arg.FrontmatterYaml,
		arg.Policy,
		arg.Visibility,
		arg.Status,
		arg.PublishedAt,
		arg.PublishedBy,
		arg.DeletedAt,
		arg.DeletedBy,
		arg.At,
		arg.ID,
		arg.ExpectedVersion,
	)
	var i UpdateProductDocumentRow
	err := row.Scan(
		&i.InternalID,
		&i.ID,
		&i.Version,
		&i.UpdatedAt,
		&i.PublishedAt,
		&i.DeletedAt,
	)
	return i, err
}
